inline const Device* find(std::string_view name) noexcept {
    std::size_t lo=0,hi=aliases.size();
    while(lo<hi){const auto mid=lo+(hi-lo)/2;if(aliases[mid].name<name)lo=mid+1;else hi=mid;}
    return lo<aliases.size()&&aliases[lo].name==name?&devices[aliases[lo].device]:nullptr;
}
inline std::string_view deviceId(std::string_view name) noexcept {const auto* d=find(name);return d?d->deviceId:std::string_view{};}
